import React from 'react';

/**
 * Renders the application-generated scores: a circular gauge for the overall
 * score plus the four component bars.
 *
 * The disclaimer supplied by the backend is always rendered directly beneath
 * the gauge. That is deliberate - the number must never appear on screen
 * without the statement that it is generated by PlacementIQ and is not a real
 * employer ATS result.
 */
const bandClass = (score) => {
  if (score >= 85) return 'ats-score-excellent';
  if (score >= 70) return 'ats-score-good';
  if (score >= 55) return 'ats-score-fair';
  if (score >= 40) return 'ats-score-weak';
  return 'ats-score-poor';
};

const ScoreBar = ({ label, value }) => (
  <div className="ats-bar-row">
    <span className="ats-bar-label">{label}</span>
    <div className="ats-bar-track">
      <div className={`ats-bar-fill ${bandClass(value ?? 0)}`} style={{ width: `${value ?? 0}%` }} />
    </div>
    <span className="ats-bar-value">{value ?? 0}</span>
  </div>
);

const AtsScoreCard = ({ analysis }) => {
  const overall = analysis.overallScore ?? 0;

  return (
    <section className="ats-card ats-score-card">
      <div className="ats-score-main">
        <div className={`ats-gauge ${bandClass(overall)}`} style={{ '--score': overall }}>
          <span className="ats-gauge-value">{overall}</span>
          <span className="ats-gauge-max">/ 100</span>
        </div>
        <div className="ats-score-meta">
          <h2 className="ats-score-band">{analysis.scoreBand}</h2>
          <p className="ats-score-context">
            PlacementIQ resume score
            {analysis.targetRole ? ` for "${analysis.targetRole}"` : ''}
          </p>
          {analysis.summary && <p className="ats-summary">{analysis.summary}</p>}
        </div>
      </div>

      <p className="ats-disclaimer">{analysis.scoreDisclaimer}</p>

      <div className="ats-bars">
        <ScoreBar label="Skills" value={analysis.skillsScore} />
        <ScoreBar label="Keywords" value={analysis.keywordScore} />
        <ScoreBar label="ATS formatting" value={analysis.formattingScore} />
        <ScoreBar label="Completeness" value={analysis.completenessScore} />
      </div>
    </section>
  );
};

export default AtsScoreCard;
